class SaldoInsuficiente(Exception):
    pass


def sacar(saldo, valor):
    if valor > saldo:
        raise SaldoInsuficiente(f"faltam {valor - saldo} reais")
    return saldo - valor


saldo = int(input("Saldo: "))
valor = int(input("Valor do saque: "))
try:
    novo = sacar(saldo, valor)
    print(f"Saque feito. Saldo agora: {novo} reais")
except SaldoInsuficiente as erro:
    print("Saque negado:", erro)

